long media_enum_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent;
    int ret = 0;
    unsigned int i = 0;

    memset(&kent, 0, sizeof(kent));

    if (!mdev || !uent)
        return -EINVAL;

    /* Iterate through all entities of the media device */
    media_device_for_each_entity(mdev, kent.ent) {
        if (copy_to_user(&kent, &kent, sizeof(kent)))
            return -EFAULT;

        if (copy_to_user(uent, &kent, sizeof(kent)))
            return -EFAULT;

        uent++;
        i++;
    }

    return ret;
}

long enumerate_media_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity *entity;
    struct media_entity_desc kent;

    if (!mdev || !uent)
        return -EINVAL;

    entity = media_device_get_entity(mdev);
    if (!entity)
        return -ENODEV;

    memset(&kent, 0, sizeof(kent));
    kent.id = entity->id;
    kent.name = entity->name;
    kent.type = entity->type;
    kent.flags = entity->flags;
    kent.group_id = entity->group_id;

    if (copy_to_user(uent, &kent, sizeof(kent)))
        return -EFAULT;

    return 0;
}

